1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #14161c;
17	    color: #e8e8ec;
18	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board {
22	    display: grid;
23	    grid-template-columns: repeat(10, 28px);
24	    grid-template-rows: repeat(20, 28px);
25	    gap: 1px;
26	    padding: 1px;
27	    background: #2a2d36;
28	    border: 2px solid #3a3e4a;
29	  }
30	  .cell { width: 28px; height: 28px; background: #0d0e12; }
31	  .side { display: flex; flex-direction: column; gap: 16px; min-width: 140px; }
32	  .panel { background: #1d2028; border: 1px solid #2f333d; padding: 10px 12px; }
33	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #8a8f9c; }
34	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
35	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
36	  .next-item[data-piece], .hold-item[data-piece] { background: transparent !important; }
37	  .hold-item { margin-top: 8px; }
38	  .preview {
39	    display: grid;
40	    grid-template-columns: repeat(4, 16px);
41	    grid-template-rows: repeat(2, 16px);
42	    gap: 1px;
43	  }
44	  .preview .mini { width: 16px; height: 16px; background: transparent; }
45	  .status { font-size: 14px; color: #ff8a8a; min-height: 18px; }
46	  button {
47	    font: inherit;
48	    background: #2f333d;
49	    color: #e8e8ec;
50	    border: 1px solid #454a57;
51	    padding: 6px 10px;
52	    cursor: pointer;
53	  }
54	  button:hover { background: #3a3e4a; }
55	  .help { font-size: 12px; color: #8a8f9c; line-height: 1.6; }
56	
57	  /* Piece colours, shared by the board and the preview. */
58	  [data-piece="I"] { background: #22c5e6 !important; }
59	  [data-piece="O"] { background: #f2d024 !important; }
60	  [data-piece="T"] { background: #a64ee6 !important; }
61	  [data-piece="S"] { background: #3fcf5a !important; }
62	  [data-piece="Z"] { background: #e8423f !important; }
63	  [data-piece="J"] { background: #3563e9 !important; }
64	  [data-piece="L"] { background: #f08a24 !important; }
65	</style>
66	</head>
67	<body>
68	<div class="game">
69	  <div class="board" data-testid="board" id="board"></div>
70	  <div class="side">
71	    <div class="panel"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
72	    <div class="panel"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
73	    <div class="panel"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
74	    <div class="panel"><div class="label">Hold</div><div class="preview hold-item" data-testid="hold-piece" id="hold" data-piece=""></div></div>
75	    <div class="panel"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
76	    <div class="status" data-testid="game-over" id="status" hidden>Game over</div>
77	    <button type="button" id="restart">New game</button>
78	    <div class="help">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop<br>C / Shift hold</div>
79	  </div>
80	</div>
81	<script>
82	(function () {
83	  "use strict";
84	
85	  var ROWS = 20;
86	  var COLS = 10;
87	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
88	  var MIN_UPCOMING = 5;
89	  // [REQ-006] Show only the next piece.
90	  var PREVIEW_COUNT = 1;
91	
92	  // Spawn shapes as [row, col] offsets from the top-left of the spawn box.
93	  var SHAPES = {
94	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
95	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
96	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
97	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
98	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
99	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
100	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
101	  };
102	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
103	  // Size of the square box each piece rotates inside.
104	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
105	  // Sideways shifts tried, in order, when a rotated shape does not fit in place.
106	  var KICKS = [0, -1, 1, -2, 2];
107	  // Locking rule (decision): 2 ticks unable to fall, left/right restarts it at most 3 times.
108	  var LOCK_TICKS = 2;
109	  var MAX_LOCK_RESETS = 3;
110	  // Scoring (decision): points by rows cleared at once, times level. Clearing rows together
111	  // must always beat clearing the same rows in smaller groups. Soft drop 1/cell, hard drop 2/cell.
112	  var LINE_SCORES = [0, 100, 300, 500, 800];
113	  var SOFT_DROP_POINTS = 1;
114	  var HARD_DROP_POINTS = 2;
115	
116	  // board[row][col] is a piece letter or null. The renderer and getBoard both read it.
117	  var board;
118	  var current;   // { type, cells, row, col, lockTicks, lockResets } or null
119	  var upcoming;  // array of piece letters, soonest first
120	  var hold;      // held piece letter or null
121	  var holdUsed;  // true once the falling piece has been held; cleared when a piece locks
122	  var score, level, lines, status;
123	  var timer = null;
124	
125	  var boardEl = document.getElementById("board");
126	  var previewEl = document.getElementById("preview");
127	  var holdEl = document.getElementById("hold");
128	  var scoreEl = document.getElementById("score");
129	  var levelEl = document.getElementById("level");
130	  var linesEl = document.getElementById("lines");
131	  var statusEl = document.getElementById("status");
132	  var cellEls = [];
133	  var previewItems = [];  // { el, minis } per upcoming piece shown, soonest first
134	  var holdMinis = [];
135	
136	  // [REQ-001] Build the 200 board cells and the preview cells once.
137	  // [REQ-004] The preview holds PREVIEW_COUNT items, each a 4x2 grid of mini cells.
138	  // [REQ-006] PREVIEW_COUNT is 1: one item, the next piece.
139	  function buildDom() {
140	    for (var r = 0; r < ROWS; r++) {
141	      cellEls.push([]);
142	      for (var c = 0; c < COLS; c++) {
143	        var el = document.createElement("div");
144	        el.className = "cell";
145	        el.setAttribute("data-testid", "cell");
146	        el.setAttribute("data-row", String(r));
147	        el.setAttribute("data-col", String(c));
148	        el.setAttribute("data-filled", "false");
149	        el.setAttribute("data-piece", "");
150	        boardEl.appendChild(el);
151	        cellEls[r].push(el);
152	      }
153	    }
154	    for (var i = 0; i < PREVIEW_COUNT; i++) {
155	      var item = document.createElement("div");
156	      item.className = "preview next-item";
157	      item.setAttribute("data-testid", "next-piece-item");
158	      item.setAttribute("data-piece", "");
159	      var minis = [];
160	      for (var k = 0; k < 8; k++) {
161	        var m = document.createElement("div");
162	        m.className = "mini";
163	        m.setAttribute("data-piece", "");
164	        item.appendChild(m);
165	        minis.push(m);
166	      }
167	      previewEl.appendChild(item);
168	      previewItems.push({ el: item, minis: minis });
169	    }
170	    // [REQ-007] The hold display: the same 4x2 grid as a preview item.
171	    for (var h = 0; h < 8; h++) {
172	      var hm = document.createElement("div");
173	      hm.className = "mini";
174	      hm.setAttribute("data-piece", "");
175	      holdEl.appendChild(hm);
176	      holdMinis.push(hm);
177	    }
178	  }
179	
180	  function emptyBoard() {
181	    var b = [];
182	    for (var r = 0; r < ROWS; r++) {
183	      var row = [];
184	      for (var c = 0; c < COLS; c++) row.push(null);
185	      b.push(row);
186	    }
187	    return b;
188	  }
189	
190	  function isType(t) { return TYPES.indexOf(t) !== -1; }
191	
192	  // [REQ-001] Random generator: a shuffled bag of all seven pieces.
193	  function randomBag() {
194	    var bag = TYPES.slice();
195	    for (var i = bag.length - 1; i > 0; i--) {
196	      var j = Math.floor(Math.random() * (i + 1));
197	      var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
198	    }
199	    return bag;
200	  }
201	
202	  function fillUpcoming() {
203	    while (upcoming.length < MIN_UPCOMING) upcoming = upcoming.concat(randomBag());
204	  }
205	
206	  function cellsOf(piece, row, col) {
207	    return piece.cells.map(function (o) { return [row + o[0], col + o[1]]; });
208	  }
209	
210	  function fits(piece, row, col) {
211	    var cells = cellsOf(piece, row, col);
212	    for (var i = 0; i < cells.length; i++) {
213	      var r = cells[i][0], c = cells[i][1];
214	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
215	      if (board[r][c]) return false;
216	    }
217	    return true;
218	  }
219	
220	  // [REQ-001] Take the next piece from the queue and place it at the top.
221	  function spawn() {
222	    fillUpcoming();
223	    var type = upcoming.shift();
224	    fillUpcoming();
225	    spawnType(type);
226	  }
227	
228	  // [REQ-004] If the new piece does not fit where it spawns, the game is over.
229	  // [REQ-007] Pieces from the queue and from hold both enter here, at the spawn position.
230	  function spawnType(type) {
231	    var piece = {
232	      type: type,
233	      cells: SHAPES[type].map(function (o) { return o.slice(); }),
234	      row: 0,
235	      col: SPAWN_COL[type],
236	      lockTicks: 0,
237	      lockResets: 0
238	    };
239	    if (!fits(piece, piece.row, piece.col)) {
240	      current = null;
241	      status = "gameover";
242	      stopTimer();
243	      return;
244	    }
245	    current = piece;
246	  }
247	
248	  // [REQ-003] Remove full rows, drop the rows above, add rows to lines and score at the current level.
249	  function clearLines() {
250	    var kept = board.filter(function (row) {
251	      return row.some(function (v) { return !v; });
252	    });
253	    var cleared = ROWS - kept.length;
254	    while (kept.length < ROWS) {
255	      var empty = [];
256	      for (var c = 0; c < COLS; c++) empty.push(null);
257	      kept.unshift(empty);
258	    }
259	    board = kept;
260	    if (cleared > 0) {
261	      score += LINE_SCORES[cleared] * level;
262	      lines += cleared;
263	      // [REQ-007] One level per 10 lines crossed, counted from the current level, so setLevel carries on.
264	      var gained = Math.floor(lines / 10) - Math.floor((lines - cleared) / 10);
265	      if (gained > 0) {
266	        level += gained;
267	        if (status === "running") startTimer();
268	      }
269	    }
270	  }
271	
272	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next piece.
273	  function lockPiece() {
274	    cellsOf(current, current.row, current.col).forEach(function (rc) {
275	      board[rc[0]][rc[1]] = current.type;
276	    });
277	    current = null;
278	    holdUsed = false;
279	    clearLines();
280	    spawn();
281	  }
282	
283	  // [REQ-007] Hold: put the falling piece aside (or swap with the held one). Once per piece.
284	  function holdPiece() {
285	    if (holdUsed) return;
286	    var type = current.type;
287	    var out = hold;
288	    hold = type;
289	    holdUsed = true;
290	    current = null;
291	    if (out) spawnType(out); else spawn();
292	  }
293	
294	  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
295	  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
296	  function gravityStep() {
297	    if (status !== "running" || !current) return;
298	    if (fits(current, current.row + 1, current.col)) {
299	      current.row += 1;
300	      current.lockTicks = 0;
301	    } else {
302	      current.lockTicks += 1;
303	      if (current.lockTicks >= LOCK_TICKS) lockPiece();
304	    }
305	  }
306	
307	  // [REQ-002] Restart the lock delay, at most 3 times per piece.
308	  // [REQ-005] Sideways moves and soft drops on a resting piece share this budget.
309	  function resetLock() {
310	    if (current.lockResets < MAX_LOCK_RESETS) {
311	      current.lockResets += 1;
312	      current.lockTicks = 0;
313	    }
314	  }
315	
316	  // [REQ-002] Sideways move. While resting, a move restarts the lock delay.
317	  function shift(dx) {
318	    if (!fits(current, current.row, current.col + dx)) return;
319	    var resting = !fits(current, current.row + 1, current.col);
320	    current.col += dx;
321	    if (resting) resetLock();
322	  }
323	
324	  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
325	  function rotateCW() {
326	    var n = BOX[current.type];
327	    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
328	    for (var i = 0; i < KICKS.length; i++) {
329	      if (fits(rotated, current.row, current.col + KICKS[i])) {
330	        current.cells = rotated.cells;
331	        current.col += KICKS[i];
332	        return;
333	      }
334	    }
335	  }
336	
337	  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW. [REQ-007] hold.
338	  // [REQ-003] Soft drop scores 1 per cell moved, hard drop 2 per cell dropped.
339	  // [REQ-005] Soft drop on a resting piece scores nothing but restarts the lock delay like a sideways move.
340	  function doInput(action) {
341	    if (status !== "running" || !current) return;
342	    if (action === "left") {
343	      shift(-1);
344	    } else if (action === "right") {
345	      shift(1);
346	    } else if (action === "rotateCW") {
347	      rotateCW();
348	    } else if (action === "softDrop") {
349	      if (fits(current, current.row + 1, current.col)) {
350	        current.row += 1;
351	        score += SOFT_DROP_POINTS;
352	      } else {
353	        resetLock();
354	      }
355	    } else if (action === "hardDrop") {
356	      while (fits(current, current.row + 1, current.col)) {
357	        current.row += 1;
358	        score += HARD_DROP_POINTS;
359	      }
360	      lockPiece();
361	    } else if (action === "hold") {
362	      holdPiece();
363	    }
364	  }
365	
366	  // [REQ-007] Gravity interval in ms for the current level.
367	  function gravityInterval() {
368	    return Math.max(100, 1000 - (level - 1) * 100);
369	  }
370	
371	  function stopTimer() {
372	    if (timer !== null) { clearInterval(timer); timer = null; }
373	  }
374	
375	  function startTimer() {
376	    stopTimer();
377	    timer = setInterval(function () {
378	      gravityStep();
379	      render();
380	    }, gravityInterval());
381	  }
382	
383	  // [REQ-001] Draw the whole game state into the DOM, synchronously.
384	  function render() {
385	    var drawn = board.map(function (row) { return row.slice(); });
386	    if (current) {
387	      cellsOf(current, current.row, current.col).forEach(function (rc) {
388	        drawn[rc[0]][rc[1]] = current.type;
389	      });
390	    }
391	    for (var r = 0; r < ROWS; r++) {
392	      for (var c = 0; c < COLS; c++) {
393	        var v = drawn[r][c] || "";
394	        var el = cellEls[r][c];
395	        if (el.getAttribute("data-piece") !== v) {
396	          el.setAttribute("data-piece", v);
397	          el.setAttribute("data-filled", v ? "true" : "false");
398	        }
399	      }
400	    }
401	    // [REQ-004] Upcoming pieces in their board colour. [REQ-006] Only the next one is shown.
402	    previewItems.forEach(function (item, i) {
403	      var type = upcoming[i] || "";
404	      item.el.setAttribute("data-piece", type);
405	      item.el.hidden = !type;
406	      item.minis.forEach(function (m) { m.setAttribute("data-piece", ""); });
407	      if (type) {
408	        SHAPES[type].forEach(function (o) {
409	          item.minis[o[0] * 4 + o[1]].setAttribute("data-piece", type);
410	        });
411	      }
412	    });
413	    // [REQ-007] Held piece in its board colour.
414	    holdEl.setAttribute("data-piece", hold || "");
415	    holdMinis.forEach(function (m) { m.setAttribute("data-piece", ""); });
416	    if (hold) {
417	      SHAPES[hold].forEach(function (o) {
418	        holdMinis[o[0] * 4 + o[1]].setAttribute("data-piece", hold);
419	      });
420	    }
421	    scoreEl.textContent = String(score);
422	    levelEl.textContent = String(level);
423	    linesEl.textContent = String(lines);
424	    statusEl.hidden = status !== "gameover";
425	  }
426	
427	  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
428	  function newGame(queue) {
429	    board = emptyBoard();
430	    score = 0;
431	    level = 1;
432	    lines = 0;
433	    hold = null;
434	    holdUsed = false;
435	    status = "running";
436	    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
437	    current = null;
438	    spawn();
439	    if (status === "running") startTimer();
440	    render();
441	  }
442	
443	  window.__tetris = {
444	    newGame: function (queue) { newGame(queue); },
445	
446	    setQueue: function (queue) {
447	      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
448	      fillUpcoming();
449	      render();
450	    },
451	
452	    setBoard: function (rows) {
453	      var b = emptyBoard();
454	      for (var r = 0; r < ROWS; r++) {
455	        var line = (rows && rows[r]) || "";
456	        for (var c = 0; c < COLS; c++) {
457	          var ch = line.charAt(c);
458	          b[r][c] = isType(ch) ? ch : null;
459	        }
460	      }
461	      board = b;
462	      render();
463	    },
464	
465	    tick: function (n) {
466	      if (n === undefined) n = 1;
467	      for (var i = 0; i < n; i++) gravityStep();
468	      if (status === "running") startTimer();
469	      render();
470	    },
471	
472	    // [REQ-007] Set the level for testing. Line levelling continues from here.
473	    setLevel: function (n) {
474	      n = Math.floor(Number(n));
475	      if (!(n >= 1)) return;
476	      level = n;
477	      if (status === "running") startTimer();
478	      render();
479	    },
480	
481	    input: function (action) {
482	      doInput(action);
483	      render();
484	    },
485	
486	    getBoard: function () {
487	      return board.map(function (row) {
488	        return row.map(function (v) { return v || "."; }).join("");
489	      });
490	    },
491	
492	    getState: function () {
493	      return {
494	        current: current
495	          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
496	          : null,
497	        next: upcoming.slice(),
498	        score: score,
499	        level: level,
500	        lines: lines,
501	        status: status,
502	        dropInterval: gravityInterval(),
503	        hold: hold
504	      };
505	    }
506	  };
507	
508	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop", c: "hold", C: "hold", Shift: "hold" };
509	
510	  document.addEventListener("keydown", function (e) {
511	    var action = KEYS[e.key];
512	    if (!action) return;
513	    e.preventDefault();
514	    window.__tetris.input(action);
515	  });
516	
517	  document.getElementById("restart").addEventListener("click", function (e) {
518	    e.currentTarget.blur();
519	    newGame();
520	  });
521	
522	  buildDom();
523	  newGame();
524	})();
525	</script>
526	</body>
527	</html>
